service.method:

SELECT
	SEAL_MG_USER_ID
	, GETUSERNAME(HOUSE_CODE, COMPANY_CODE, SEAL_MG_USER_ID, 'KO') AS SEAL_MG_USER_NAME
	, GETUSERDEPTNAME(HOUSE_CODE, COMPANY_CODE, SEAL_MG_USER_ID, 'KO') AS SEAL_MG_DEPT_NAME
	, ( select `position` from SUSMT where USER_ID = SEAL_MG_USER_ID and HOUSE_CODE = ${HOUSE_CODE}
			AND COMPANY_CODE = ${COMPANY_CODE}
	  ) AS SEAL_MG_USER_POSITION
	, ( select `employee_no` from SUSMT where USER_ID = SEAL_MG_USER_ID and HOUSE_CODE = ${HOUSE_CODE}
			AND COMPANY_CODE = ${COMPANY_CODE}
	  ) AS SEAL_MG_EMPLOYEE_NO 
	, SUB_MG_USER_ID 
	, GETUSERNAME(HOUSE_CODE, COMPANY_CODE, SUB_MG_USER_ID, 'KO') AS SUB_MG_USER_NAME
	, GETUSERDEPTNAME(HOUSE_CODE, COMPANY_CODE, SUB_MG_USER_ID, 'KO') AS SUB_MG_DEPT_NAME
	, ( select `position` from SUSMT where USER_ID = SUB_MG_USER_ID and HOUSE_CODE = ${HOUSE_CODE}
			AND COMPANY_CODE = ${COMPANY_CODE}
	  ) AS SUB_MG_USER_POSITION
  	, ( select `employee_no` from SUSMT where USER_ID = SUB_MG_USER_ID and HOUSE_CODE = ${HOUSE_CODE}
			AND COMPANY_CODE = ${COMPANY_CODE}
	  ) AS SUB_MG_EMPLOYEE_NO
FROM
	SSEAL 
WHERE
	HOUSE_CODE = ${HOUSE_CODE}
	AND COMPANY_CODE = ${COMPANY_CODE}
	AND MANAGE_NUMBER IN ($INS{manageNo_Arr})
